using System;using System.IO;using System.Drawing;using System.Drawing.Printing;using System.Reflection;using System.Windows.Forms;using EanEtikety;
class PrintingTests {
 static string dir;static void Check(bool v,string m){if(!v)throw new Exception(m);}static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Snap(Form f,string name){using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(dir,name+".png"));}}
 [STAThread]static void Main(string[] args){dir=Path.GetFullPath(args[0]);Directory.CreateDirectory(dir);try{Run();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS: preview first, zoom, page navigation, shared immutable layout, cancel restores settings, printer copies and orientation, multipage preview, empty input, undersized paper, millimetre bounds. No physical printer job sent.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
 static void Run(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var s=LabelSettings.Default();s.UsePaper=true;s.PageWidth=210;s.PageHeight=297;s.MarginX=12;s.MarginY=15;s.MarginRight=7;s.MarginBottom=9;s.Symbols.Add(new SymbolItem{X=45,Y=28,Width=10,Height=10*DepositArt.Aspect});s.Copies=3;
  using(var doc=new LabelPrintDocument(s)){Check(doc.PageCount==3,"multipage count");s.MarginX=99;Check(doc.LabelBounds(0).X==12,"immutable layout");Check(!doc.FitsPaper(new Rectangle(0,0,100,100)),"small paper rejected");
   using(var f=new PrintPreviewWindow(doc)){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();Check(!Field<Button>(f,"print").Enabled,"cannot silently print default device");var zoom=Field<ComboBox>(f,"zoom");zoom.SelectedIndex=3;Check(Field<PrintPreviewControl>(f,"preview").Zoom==1.5,"zoom");zoom.SelectedIndex=0;Field<NumericUpDown>(f,"page").Value=3;Check(Field<PrintPreviewControl>(f,"preview").StartPage==2,"page switching");short oldCopies=doc.PrinterSettings.Copies;var oldLandscape=doc.DefaultPageSettings.Landscape;
    Check(!f.ConfigurePrinter(d=>{doc.PrinterSettings.Copies=7;doc.DefaultPageSettings.Landscape=!oldLandscape;return DialogResult.Cancel;}),"cancel result");Check(doc.PrinterSettings.Copies==oldCopies&&doc.DefaultPageSettings.Landscape==oldLandscape,"cancel rollback");Check(!f.Submitted,"cancel sends nothing");
    Check(f.ConfigurePrinter(d=>{doc.PrinterSettings.Copies=2;doc.DefaultPageSettings.Landscape=true;return DialogResult.OK;}),"orientation accepted without scaling");Check(doc.PrinterSettings.Copies==2&&doc.DefaultPageSettings.Landscape,"selected settings preserved");Field<NumericUpDown>(f,"page").Value=1;for(int tick=0;tick<10;tick++){Snap(f,"preview-window");Application.DoEvents();System.Threading.Thread.Sleep(100);}Snap(f,"preview-window");f.Close();Check(!f.Submitted,"close sends nothing");
   }
   var controller=new PreviewPrintController{UseAntiAlias=true};doc.PrintController=controller;doc.Print();var pages=controller.GetPreviewPageInfo();Check(pages.Length==3,"preview page count");using(var b=new Bitmap(1123,794))using(var g=Graphics.FromImage(b)){g.Clear(Color.White);g.DrawImage(pages[0].Image,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.Combine(dir,"landscape-preview.png"));}foreach(var p in pages)p.Image.Dispose();
  }
  bool empty=false;try{var e=LabelSettings.Default();e.Ean="";e.Texts.Clear();using(var d=new LabelPrintDocument(e)){} }catch(InvalidOperationException){empty=true;}Check(empty,"empty document handled");
  var sheet=LabelSettings.Default();sheet.Sheet=true;sheet.Copies=31;using(var d=new LabelPrintDocument(sheet)){Check(d.PageCount==3&&d.Capacity==15,"legacy sheet pagination");using(var b=new Bitmap(840,1188))using(var g=Graphics.FromImage(b)){g.Clear(Color.White);Check(d.RenderPage(g,2)==1,"partial last page");}}
  string pdfPrinter=null;foreach(string name in PrinterSettings.InstalledPrinters)if(name=="Microsoft Print to PDF")pdfPrinter=name;
  if(pdfPrinter==null){File.WriteAllText(Path.Combine(dir,"pdf-unavailable.txt"),"Microsoft Print to PDF is not installed.");return;}
  var settings=LabelSettings.Default();settings.UsePaper=true;settings.PageWidth=210;settings.PageHeight=297;settings.MarginX=12;settings.MarginY=15;settings.MarginRight=7;settings.MarginBottom=9;settings.Copies=3;settings.Symbols.Add(new SymbolItem{X=45,Y=28,Width=10,Height=10*DepositArt.Aspect});
  using(var pdf=new LabelPrintDocument(settings)){pdf.PrinterSettings.PrinterName=pdfPrinter;foreach(PaperSize size in pdf.PrinterSettings.PaperSizes)if(size.Kind==PaperKind.A4){pdf.DefaultPageSettings.PaperSize=size;break;}pdf.DefaultPageSettings.Landscape=false;pdf.PrinterSettings.Copies=1;pdf.PrinterSettings.PrintToFile=true;pdf.PrinterSettings.PrintFileName=Path.Combine(dir,"windows-print.pdf");pdf.ValidatePrinter();Check(pdf.PrinterSettings.PrinterName=="Microsoft Print to PDF","virtual printer only");pdf.PrintController=new StandardPrintController();pdf.Print();File.WriteAllText(Path.Combine(dir,"pdf-submitted.txt"),"Microsoft Print to PDF job submitted: 3 A4 pages. No physical printer used.");}
 }
}

